import Foundation
import ArgumentParser
import MacosDefaultsCore

/// Write a line to stderr.
func printError(_ message: String) {
    FileHandle.standardError.write(Data((message + "\n").utf8))
}

/// Read a file's text, or print an error to stderr and exit 2.
func readFileOrExit(_ path: String, label: String) throws -> String {
    do {
        return try String(contentsOfFile: path, encoding: .utf8)
    } catch {
        printError("error: cannot read \(label) file '\(path)': \(error.localizedDescription)")
        throw ExitCode(2)
    }
}

/// Parse a state file from a path, mapping read + parse errors to stderr + exit 2.
func loadStateFileOrExit(_ path: String) throws -> [StateEntry] {
    let text = try readFileOrExit(path, label: "statefile")
    do {
        return try StateFile.parse(text)
    } catch let StateFileError.malformedLine(lineNumber, content, reason) {
        printError("error: \(path):\(lineNumber): malformed line (\(reason)): \(content)")
        throw ExitCode(2)
    }
}

import XCTest
@testable import MacosDefaultsCore

final class PrefValueTests: XCTestCase {
    func testTypeTokens() {
        XCTAssertEqual(PrefValue.bool(true).typeToken, "bool")
        XCTAssertEqual(PrefValue.int(1).typeToken, "int")
        XCTAssertEqual(PrefValue.double(1.5).typeToken, "float")
        XCTAssertEqual(PrefValue.string("x").typeToken, "string")
        XCTAssertEqual(PrefValue.unsupported("CFArray").typeToken, "unsupported")
    }

    func testSerialized() {
        XCTAssertEqual(PrefValue.bool(true).serialized, "true")
        XCTAssertEqual(PrefValue.bool(false).serialized, "false")
        XCTAssertEqual(PrefValue.int(42).serialized, "42")
        XCTAssertEqual(PrefValue.int(-7).serialized, "-7")
        XCTAssertEqual(PrefValue.double(1.5).serialized, "1.5")
        XCTAssertEqual(PrefValue.double(0.1).serialized, "0.1")
        XCTAssertEqual(PrefValue.string("hello world").serialized, "hello world")
        XCTAssertEqual(PrefValue.unsupported("CFArray").serialized, "<unsupported CFArray>")
    }
}

import XCTest
@testable import MacosDefaultsCore

final class ReloadTests: XCTestCase {
    func testDefaultAgentList() {
        XCTAssertEqual(defaultReloadAgents, ["Dock", "Finder", "SystemUIServer"])
    }

    func testReloadInvokesRunnerForEachAgent() {
        var called: [String] = []
        reloadUI(agents: ["A", "B"]) { called.append($0) }
        XCTAssertEqual(called, ["A", "B"])
    }
}

import XCTest
@testable import MacosDefaultsCore

final class NoiseFilterTests: XCTestCase {
    func testStarMatches() {
        let f = NoiseFilter(patterns: ["* Frame", "*Recent*", "NSWindow Frame *"])
        XCTAssertTrue(f.matches("Browser Window Frame"))   // matches "* Frame"
        XCTAssertTrue(f.matches("RecentDocuments"))        // matches "*Recent*"
        XCTAssertTrue(f.matches("NSWindow Frame Main"))    // matches "NSWindow Frame *"
        XCTAssertFalse(f.matches("ShowPathbar"))
        XCTAssertFalse(f.matches("tilesize"))
    }

    func testQuestionMarkAndClasses() {
        let f = NoiseFilter(patterns: ["key?", "v[0-9]"])
        XCTAssertTrue(f.matches("key1"))
        XCTAssertFalse(f.matches("key"))      // ? requires exactly one char
        XCTAssertTrue(f.matches("v3"))
        XCTAssertFalse(f.matches("vx"))
    }

    func testEmptyFilterMatchesNothing() {
        let f = NoiseFilter(patterns: [])
        XCTAssertFalse(f.matches("anything"))
    }

    func testParseLineListIgnoresCommentsAndBlanks() {
        let text = """
        # comment
        com.apple.finder

        NSGlobalDomain
        """
        XCTAssertEqual(parseLineList(text), ["com.apple.finder", "NSGlobalDomain"])
    }
}
